import{_ as t,o,c as d,a0 as c}from"./chunks/framework.Bmhw_dvp.js";const m=JSON.parse('{"title":"사용 통계와 끄는 법","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://dira.proofer.tech/docs/analytics"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"dira"}],["meta",{"property":"og:locale","content":"ko_KR"}],["meta",{"property":"og:url","content":"https://dira.proofer.tech/docs/analytics"}],["meta",{"property":"og:title","content":"사용 통계와 끄는 법"}],["meta",{"property":"og:description","content":"티켓을 큐에 넣으면 cron에 물린 워커가 claude 세션에 넘깁니다. 파일시스템이 곧 큐인 티켓 디스패처."}],["meta",{"property":"og:image","content":"https://dira.proofer.tech/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"name":"twitter:card","content":"summary_large_image"}]]},"headers":[],"relativePath":"docs/analytics.md","filePath":"docs/analytics.md"}'),a={name:"docs/analytics.md"};function r(s,e,i,n,p,l){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="사용-통계와-끄는-법" tabindex="-1">사용 통계와 끄는 법 <a class="header-anchor" href="#사용-통계와-끄는-법" aria-label="Permalink to &quot;사용 통계와 끄는 법&quot;">​</a></h1><p>앱(<code>dira teams</code>)은 GA4로 사용 통계를 보냅니다. 엔진(<code>tick.sh</code>·<code>tickets.py</code>)은 아무것도 보내지 않습니다. 이 장이 다루는 것은 전부 앱 쪽 이야기입니다.</p><h2 id="보내는-것-—-이벤트-8종" tabindex="-1">보내는 것 — 이벤트 8종 <a class="header-anchor" href="#보내는-것-—-이벤트-8종" aria-label="Permalink to &quot;보내는 것 — 이벤트 8종&quot;">​</a></h2><p>이름 8개가 전부입니다. 코드에 이 표에 없는 이벤트가 생긴다면 그것은 결함입니다.</p><table tabindex="0"><thead><tr><th>이벤트</th><th>언제</th><th>파라미터</th></tr></thead><tbody><tr><td><code>app_open</code></td><td>사용자 세션이 시작될 때(첫 이벤트 앞·30분 무활동 뒤 재시작)</td><td><code>app_version</code>, <code>shell</code>(<code>desktop</code>|<code>browser</code>)</td></tr><tr><td><code>screen_view</code></td><td>화면 진입</td><td><code>screen</code>(<code>root</code>|<code>board</code>|<code>ticket</code>|<code>workers</code>|<code>personas</code>|<code>protocols</code>|<code>home</code>)</td></tr><tr><td><code>project_add</code></td><td>프로젝트가 하나 늘었을 때</td><td><code>method</code>(<code>create</code>|<code>register</code>)</td></tr><tr><td><code>worker_create</code></td><td>워커 생성 성공</td><td><code>engine</code>(<code>claude</code>|<code>codex</code>|<code>other</code>), <code>cron_ok</code>(bool)</td></tr><tr><td><code>ticket_create</code></td><td>티켓 발행·요구 접수 성공</td><td><code>kind</code>(<code>work</code>|<code>request</code>|<code>feedback</code>)</td></tr><tr><td><code>answer_submit</code></td><td>답변 왕복의 답을 사람이 썼을 때</td><td>없음</td></tr><tr><td><code>feedback_submit</code></td><td>의견 보내기 폼에서 보내기를 눌렀을 때</td><td>없음</td></tr><tr><td><code>analytics_off</code></td><td>통계를 끌 때(끄기 직전 마지막 한 번)</td><td>없음</td></tr></tbody></table><p>값은 개수·불리언·미리 정한 enum뿐입니다. <code>.done</code> 전환이나 디스패치처럼 엔진이 만드는 사실은 이벤트가 아닙니다. 화면 동작만 셉니다. 에러와 크래시도 보내지 않습니다.</p><h2 id="보내지-않는-것" tabindex="-1">보내지 않는 것 <a class="header-anchor" href="#보내지-않는-것" aria-label="Permalink to &quot;보내지 않는 것&quot;">​</a></h2><p>아래는 어떤 이벤트의 어떤 파라미터에도 들어가지 않습니다.</p><p>파일 경로 · 프로젝트 이름 · 큐 루트 · 티켓 해시 · 티켓 제목 · 티켓 본문 · 페르소나 이름 · 워커 이름 · 사람 이름 · 토큰 · 프롬프트(에이전트에 넣는 지시나 에이전트의 출력) · IP를 유추할 값.</p><p><code>screen_view</code>도 URL 자체는 안 보냅니다. <code>/p/&lt;project&gt;/tickets/&lt;hash&gt;</code>는 프로젝트 이름과 티켓 해시를 둘 다 담고 있어서, 보내는 것은 그 경로를 미리 정한 화면 이름(<code>ticket</code> 등) 하나로 바꾼 값입니다. 의견 보내기 폼에 쓰신 자유 입력도 GA로 가지 않습니다. 그건 GitHub 이슈로만 가고, GA에는 &quot;보낸 사실&quot;(<code>feedback_submit</code>)만 남습니다.</p><h2 id="전송-조건-—-자격값-두-개" tabindex="-1">전송 조건 — 자격값 두 개 <a class="header-anchor" href="#전송-조건-—-자격값-두-개" aria-label="Permalink to &quot;전송 조건 — 자격값 두 개&quot;">​</a></h2><p>전송은 <code>GA_MEASUREMENT_ID</code>·<code>GA_API_SECRET</code> 두 값이 있어야 나갑니다. 이 둘은 릴리스 빌드에만 CI가 넣고, 레포에는 커밋되지 않습니다. <strong>값이 없으면 코드가 아무것도 보내지 않습니다.</strong><code>pnpm dev</code>로 띄운 개발 서버와 손으로 빌드한 <code>.app</code>은 둘 다 이 상태입니다. 개발 중에 도는 세션이 통계를 오염시키지 않는 이유가 이것입니다.</p><p><code>설정</code> 다이얼로그의 사용 통계 구획도 이 값의 유무를 그대로 보여줍니다. 자격값이 없는 빌드에서는 켜짐/꺼짐 버튼과 무관하게 &quot;보내지 않습니다&quot;로 뜹니다.</p><h2 id="끄는-법" tabindex="-1">끄는 법 <a class="header-anchor" href="#끄는-법" aria-label="Permalink to &quot;끄는 법&quot;">​</a></h2><p>우측 위 톱니바퀴 → <code>설정</code> 다이얼로그의 <strong>세 번째 구획</strong>입니다(첫 번째는 인증 토큰, 두 번째는 키설정, <a href="/docs/screens">화면 소개</a> 참고). 기본은 켜짐이고, 버튼 하나로 끄시면 됩니다. 끄면 그 순간부터 아무 이벤트도 나가지 않습니다.</p><h2 id="지우는-법" tabindex="-1">지우는 법 <a class="header-anchor" href="#지우는-법" aria-label="Permalink to &quot;지우는 법&quot;">​</a></h2><p>통계 파일은 <code>~/.config/dira/analytics.json</code> 하나입니다. 여기 사는 값은 <code>install_id</code>(GA4에 보내는 익명 설치 식별자)와 <code>enabled</code>(껐을 때만 <code>false</code>로 적힙니다) 둘뿐입니다. 파일을 지우면 다음 실행에서 새 <code>install_id</code>가 발급되고, 이전 통계와 이어지지 않는 새 설치로 잡힙니다. 아래 한 줄을 터미널에 입력하시면 됩니다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/dira/analytics.json</span></span></code></pre></div><p>무엇을 왜 보내는지, 보존 기간과 위탁처는 <a href="/privacy">개인정보처리방침</a>에 있습니다.</p><p>다음은 <a href="/docs/closing">마치면서</a>입니다.</p>',20)])])}const _=t(a,[["render",r]]);export{m as __pageData,_ as default};
